
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_pw86_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_pw86", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.289934197734929e+00, -4.209894775818638e+00, -4.098018774425152e+00, -3.943611209351356e+00, -3.734349775345364e+00, -3.458019691544241e+00, -3.106102208846279e+00, -2.678799745623054e+00, -2.188157697530231e+00, -1.655635067368747e+00, -1.113354029601156e+00, -7.105218228051540e-01, -5.990570746141658e-01, -5.043807533367547e-01, -3.791254706363302e-01, -2.486249221281136e-01, -1.388358620229539e-01, -6.439405149724663e-02, -2.439594825409348e-02, -6.508154923838987e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


